long combatManager::getDistance(long start, long stop)
{
    int sx = gridX(start);
    int sy = gridY(start);
    int tx = gridX(stop);
    int ty = gridY(stop);
    long a = (sy + 1) / 2 - (ty + 1) / 2 - sx + tx;
    long b = ty / 2 - sy / 2 - sx + tx;
    if ((a < 0) == (b < 0))
        return max(abs(a), abs(b));  // DC 0x62ed8: includes.h wrapper.
    return abs(a) + abs(b);
}

